SELECT 'fungsi alamat ada' AS butir, IF((SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name IN ('isian_rtf_alamat_rapi','isian_rtf_alamat_padat','isian_rtf_alamat_kunci','isian_rtf_alamat_tingkat','isian_rtf_alamat_sah','isian_rtf_alamat_provinsi','isian_rtf_alamat_mirip','isian_rtf_alamat_ekor','isian_rtf_alamat_inti','isian_rtf_alamat') AND routine_comment LIKE 'AG:%') = 10, 1, 0) AS cocok;
